# generated by tools/ail2py.py from points_energy_main.ail; edit the .ail until onelang s16
# Input: little-endian binary64 pairs (x, y). Output: one x*x+y*y per pair.
from binary_float64 import *
from ail import read_bytes, write_bytes
import sys

class Point:

    def __init__(self, x: float, y: float):
        self.x = x
        self.y = y

def point_energies(points: list[Point]) -> list[float]:
    return [point.x * point.x + point.y * point.y for point in points]

def main() -> int:
    if len(sys.argv) != 3:
        print('usage: points_energy <input-f64le-pairs> <output-f64le>', file=sys.stderr)
        return 2
    try:
        values = unpack_float64(read_bytes(sys.argv[1]), 0)
        if len(values) % 2 != 0:
            raise ValueError()
        points: list[Point] = []
        for index in range(0, len(values), 2):
            points.append(Point(values[index], values[index + 1]))
        energies = point_energies(points)
        write_bytes(sys.argv[2], pack_float64(energies, 0))
    except OSError:
        print('point data file error', file=sys.stderr)
        return 3
    except ValueError:
        print('point data must contain complete binary64 pairs', file=sys.stderr)
        return 4
    return 0

if __name__ == "__main__":
    sys.exit(main())
